// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(address caller, address adr) internal {
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(caller != address(this));
        vm.assume(caller != address(0));
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.multiplicate{value: 0}(adr) {} catch { return; }
        reverted = false;
        assertTrue(!reverted);
    }

    function testFuzz_run(address caller, address adr) public {
        vm.assume(caller.code.length == 0 && uint160(caller) > 0xffff && caller != address(this) && caller != address(c) && caller != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && caller != 0x000000000000000000636F6e736F6c652e6c6f67 && caller != 0x4e59b44847b379578588920cA78FbF26c0B4956C && caller != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        vm.assume(adr.code.length == 0 && uint160(adr) > 0xffff && adr != address(this) && adr != address(c) && adr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && adr != 0x000000000000000000636F6e736F6c652e6c6f67 && adr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && adr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(caller, adr);
    }

    receive() external payable {}
}
